if (!function_exists('brand_icon')) {
    /**
     * Render official brand logo SVG (filled, Simple Icons paths) for social media.
     * Unknown names fall back to lucide_icon().
     */
    function brand_icon(string $name, string $class = 'w-4 h-4'): string
    {
